<template><main class="zj-workspace"><header class="zj-heading"><div><div class="zj-eyebrow">众基消防 / 维保卡生成</div><h1>维保卡生成</h1><p>填写、预览，再保存为可打印的 A4 横向维保卡。附带资料在独立栏目管理。</p></div><el-button type="primary" icon="Plus" @click="create" v-hasPermi="['management:wbcard:add']">生成维保卡</el-button></header><section class="zj-card"><div class="zj-filters"><el-input v-model="query.title" clearable placeholder="搜索项目名称" @keyup.enter="search"/><el-input v-model="query.code" clearable placeholder="维保卡编号" @keyup.enter="search"/><el-button type="primary" @click="search">查询</el-button><el-button @click="query.title='';query.code='';search()">清空</el-button><el-button @click="load">刷新</el-button></div><el-alert v-if="error" title="加载失败，请刷新重试" type="error" :closable="false"/><el-table v-loading="loading" :data="rows" empty-text="暂无维保卡，可先填写内容并预览"><el-table-column prop="title" label="项目名称" min-width="240"/><el-table-column prop="code" label="维保卡编号" min-width="170"/><el-table-column label="打印 / 邮寄" width="220"><template #default="{row}"><el-tag :type="row.printCheck==='Y'?'success':'info'">{{row.printCheck==='Y'?'已打印':'未打印'}}</el-tag> <el-tag :type="row.sendCheck==='Y'?'success':'info'">{{row.sendCheck==='Y'?'已邮寄':'未邮寄'}}</el-tag><div><el-button link size="small" @click="status(row,'printCheck')" v-hasPermi="['management:wbcard:edit']">切换打印记录</el-button><el-button link size="small" @click="status(row,'sendCheck')" v-hasPermi="['management:wbcard:edit']">切换邮寄记录</el-button></div></template></el-table-column><el-table-column label="文件" min-width="220"><template #default="{row}"><el-button v-for="(file,index) in links(row.file)" :key="file" link type="primary" @click="show(file,row.title)">{{index===0?'维保卡预览 / 打印':'历史附带资料 '+index}}</el-button><span v-if="!row.file">没有文件</span></template></el-table-column><el-table-column prop="remark" label="备注" min-width="160"/><el-table-column label="操作" width="80"><template #default="{row}"><el-button link type="danger" @click="remove(row)" v-hasPermi="['management:wbcard:remove']">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="query.pageNum" :page-size="20" :total="total" layout="total,prev,pager,next" @current-change="load"/></section>
<el-drawer v-model="open" title="生成维保卡" size="min(860px,96vw)" :close-on-click-modal="false" :before-close="close"><el-alert title="系统自动换行并适配字号；内容无法完整排版时会提示精简。预览不保存、不产生历史记录。" type="info" :closable="false"/><el-form ref="refForm" :model="form" :rules="rules" label-position="top" :disabled="busy"><div class="zj-grid"><el-form-item label="维保卡编号" prop="no"><el-input v-model="form.no" maxlength="100"/></el-form-item><el-form-item label="项目名称" prop="name"><el-input v-model="form.name" type="textarea" maxlength="255" :autosize="{minRows:1,maxRows:4}"/></el-form-item><el-form-item label="维护保养机构（章）" prop="company"><el-input v-model="form.company" maxlength="255"/></el-form-item><el-form-item label="从联系人中选用"><el-select v-model="contactId" clearable filterable remote :remote-method="findContacts" :loading="contactsLoading" placeholder="搜索姓名或电话" @visible-change="v=>v&&findContacts('')" @change="choose"><el-option v-for="c in contacts" :key="c.id" :value="c.id" :label="c.name+' · '+c.phone"/></el-select></el-form-item><el-form-item label="项目负责人" prop="leader"><el-input v-model="form.leader" maxlength="100"/></el-form-item><el-form-item label="联系电话" prop="phone"><el-input v-model="form.phone" maxlength="255"/></el-form-item><el-form-item label="维护开始日期" prop="start"><el-date-picker v-model="form.start" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="维护结束日期" prop="end"><el-date-picker v-model="form.end" value-format="YYYY-MM-DD"/></el-form-item></div><el-form-item label="维护保养内容" prop="system1"><div><el-checkbox-group v-model="systems" @change="selectSystems"><el-checkbox v-for="s in systemOptions" :key="s" :label="s" :value="s"/></el-checkbox-group><el-input v-model="form.system1" type="textarea" :rows="4" maxlength="4000" show-word-limit placeholder="可选择常用消防系统后直接编辑完整内容，无需人工按行拆分"/></div></el-form-item></el-form><template #footer><el-button @click="close(()=>open=false)" :disabled="busy">取消</el-button><el-button :loading="previewing" :disabled="saving" @click="previewForm">预览排版</el-button><el-button type="primary" :loading="saving" :disabled="previewing" @click="save">生成并保存</el-button></template></el-drawer><PdfPreview v-model="previewOpen" :url="pdfUrl" :title="pdfTitle"/></main></template>
<script setup>
import {onBeforeRouteLeave} from 'vue-router';
import {cardList,generateCard,previewCard,saveCard,removeCard,resourceList} from '@/api/wbcardWorkspace';import {fileUrl} from '@/utils/files';import PdfPreview from './components/PdfPreview.vue';import '@/assets/styles/zhongji.scss';
const {proxy}=getCurrentInstance();const query=reactive({title:'',code:'',pageNum:1,pageSize:20}),rows=ref([]),total=ref(0),loading=ref(false),error=ref(false),open=ref(false),saving=ref(false),previewing=ref(false),busy=computed(()=>saving.value||previewing.value),form=ref({}),refForm=ref(),contactId=ref(null),contacts=ref([]),contactsLoading=ref(false),previewOpen=ref(false),pdfUrl=ref(''),pdfTitle=ref(''),systems=ref([]);let snapshot='',sequence=0,contactSequence=0,blobUrl='';
const systemOptions=['火灾自动报警系统','火灾应急照明及疏散指示系统','消防电话系统','消防广播系统','消防电梯系统','消防供电设施','消防供水系统','自动喷水灭火系统','消火栓系统','机械排烟系统','机械加压送风系统','防火分隔设施','电气火灾监控系统','自动寻的灭火装置','气体灭火系统','泡沫灭火系统','细水雾灭火系统','灭火器（检查）'];
const rules=Object.fromEntries(['no','name','company','leader','phone','system1','start'].map(k=>[k,[{required:true,message:'请填写此项',trigger:'blur'}]]));rules.end=[{validator:(_r,v,cb)=>!v?cb(new Error('请选择结束日期')):v<form.value.start?cb(new Error('结束日期不能早于开始日期')):cb(),trigger:'change'}];
async function load(){const n=++sequence;loading.value=true;error.value=false;try{const r=await cardList({...query});if(n===sequence){rows.value=r.rows;total.value=r.total}}catch{if(n===sequence){rows.value=[];total.value=0;error.value=true}}finally{if(n===sequence)loading.value=false}}
function search(){query.pageNum=1;load()}function links(s){return (s||'').split(',').filter(Boolean)}
function create(){form.value={no:'',name:'',company:'河南众基消防技术有限公司',leader:'',phone:'',start:'',end:'',system1:''};systems.value=[];contactId.value=null;snapshot=JSON.stringify(form.value);open.value=true}
async function close(done){if(busy.value)return;if(snapshot!==JSON.stringify(form.value)){try{await proxy.$modal.confirm('放弃未保存的维保卡内容？')}catch{return}}done()}
function selectSystems(){form.value.system1=systems.value.join('、')}
async function findContacts(name){const n=++contactSequence;contactsLoading.value=true;try{const r=await resourceList('contacts',{name,pageNum:1,pageSize:20});if(n===contactSequence)contacts.value=r.rows}finally{if(n===contactSequence)contactsLoading.value=false}}
function choose(id){const c=contacts.value.find(c=>c.id===id);if(c){form.value.leader=c.name;form.value.phone=c.phone}}
function payload(){return {...form.value,time:form.value.start.replace(/-/g,'年').replace(/年(\d{2})$/,'月$1日')+' 至 '+form.value.end.replace(/-/g,'年').replace(/年(\d{2})$/,'月$1日')}}
function clearBlob(){if(blobUrl){URL.revokeObjectURL(blobUrl);blobUrl=''}}
function show(url,title){clearBlob();pdfUrl.value=fileUrl(url);pdfTitle.value=title;previewOpen.value=true}
async function previewForm(){if(!await refForm.value.validate().catch(()=>false))return;previewing.value=true;try{const blob=await previewCard(payload());if(blob.type.includes('json')){const r=JSON.parse(await blob.text());throw new Error(r.msg||'预览失败')}clearBlob();blobUrl=URL.createObjectURL(blob);pdfUrl.value=blobUrl;pdfTitle.value=form.value.name+'（未保存预览）';previewOpen.value=true}catch(e){proxy.$modal.msgError(e.message||'预览失败')}finally{previewing.value=false}}
async function save(){if(busy.value)return;if(!await refForm.value.validate().catch(()=>false))return;saving.value=true;try{const r=await generateCard(payload());open.value=false;show(r.data.file,form.value.name);proxy.$modal.msgSuccess('维保卡已生成，未生成附带资料');await load()}finally{saving.value=false}}
async function status(row,key){await proxy.$modal.confirm(`确认将此记录标记为${row[key]==='Y'?'未':'已'}${key==='printCheck'?'打印':'邮寄'}？`);await saveCard({id:row.id,[key]:row[key]==='Y'?'N':'Y'});await load()}
async function remove(row){await proxy.$modal.confirm('确认删除“'+row.title+'”的维保卡记录？原文件保留。');await removeCard(row.id);await load()}onBeforeUnmount(clearBlob);onMounted(load);
onBeforeRouteLeave(async()=>{if(open.value&&snapshot!==JSON.stringify(form.value)){try{await proxy.$modal.confirm('离开并放弃未保存的内容？')}catch{return false}}return true});
</script>
